const input = $input.first().json ?? {};
let body = input.body ?? input;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch { return []; }
}
const data = body?.data ?? {};
const key = data?.key ?? {};
const fromMe = key.fromMe === false || String(key.fromMe).toLowerCase() === 'false';
if (body?.event !== 'messages.upsert' || !fromMe) return [];
const messageId = String(key.id ?? '').trim();
if (!messageId) return [];
const jid = [key.remoteJidAlt, key.remoteJid, data.remoteJid]
  .map(value => String(value ?? '').trim())
  .find(value => value.endsWith('@s.whatsapp.net'));
if (!jid) return [];
const telefone = jid.slice(0, -'@s.whatsapp.net'.length);
if (!/^\d{10,15}$/.test(telefone)) return [];
const instancia = String(body.instance ?? 'evolution').trim();
const fx_UUID = ['evo', instancia, messageId].join(':');

// O emissor precisa do timestamp ORIGINAL do evento, nunca a hora do n8n.
const timeRaw = data.messageTimestamp ?? data.key?.messageTimestamp ?? body.messageTimestamp;
const secondsCandidate = typeof timeRaw === 'object' && timeRaw !== null ? timeRaw.low : timeRaw;
// Null, empty, boolean or malformed timestamps must never become epoch zero.
const originalTimePresent = (typeof secondsCandidate === 'number' ||
  (typeof secondsCandidate === 'string' && /^\d{1,10}$/.test(secondsCandidate.trim()))) &&
  secondsCandidate !== '';
const seconds = originalTimePresent ? Number(secondsCandidate) : NaN;
const occurredAt = Number.isSafeInteger(seconds) && seconds > 0 && seconds <= 2147483647
  ? seconds : null;

// FUNIX: classificação determinística; nenhuma chamada de IA.
let mensagem = data.message ?? {};
for (let nivel = 0; nivel < 5; nivel++) {
  const encapsulada = mensagem.ephemeralMessage?.message
    ?? mensagem.viewOnceMessage?.message
    ?? mensagem.viewOnceMessageV2?.message;
  if (!encapsulada) break;
  mensagem = encapsulada;
}
const textoEntrada = String(mensagem.conversation ?? mensagem.extendedTextMessage?.text ?? '');
const normalizarMensagem = texto => String(texto ?? '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/[!?.,;:]+/g, ' ').replace(/\s+/g, ' ').trim();
const textoNormalizado = normalizarMensagem(textoEntrada);
const mensagensVagas = new Map([
  ['ola posso ter mais informacoes sobre isso', ''],
  ['ola tenho interesse na vaga de polidor', 'Polidor'],
  ['ola tenho interesse na vaga de pintor', 'Pintor'],
]);
const candidato = mensagensVagas.has(textoNormalizado);
const tipoAtendimento = candidato ? 'Candidato' : 'Lead';
const vagaInteresse = candidato ? mensagensVagas.get(textoNormalizado) : '';

return [{ json: {
  tipoAtendimento,
  vagaInteresse,
  instancia,
  nome: String(data.pushName ?? '').trim(),
  telefone,
  telefoneE164: '+' + (telefone.startsWith('55') && telefone.length === 12 && /^[6-9]$/.test(telefone[4]) ? telefone.slice(0, 4) + '9' + telefone.slice(4) : telefone),
  whatsappJid: jid,
  mensagemId: messageId,
  fx_UUID,
  occurredAt
} }];

