const contato = $('Code in JavaScript').first().json;
const texto = value => String(value ?? '').replace(/`/g, '').trim();
const normalizarTelefone = value => {
  let n = texto(value).replace(/\D/g, '');
  if (!n) return '';
  if (!n.startsWith('55')) n = '55' + n;
  let local = n.slice(2);
  if (local.length === 8 || local.length === 9) local = '31' + local;
  if (local.length === 10 && /^[6-9]$/.test(local[2])) local = local.slice(0,2) + '9' + local.slice(2);
  return /^\d{10,11}$/.test(local) ? '+55' + local : '';
};
const linhas = $input.all().map(item => item.json).filter(row => typeof row.id === 'string' && row.id.trim());
const entidades = linhas.filter(row => normalizarTelefone(row.Contato ?? row.values?.['c-sGdV1LQKr3']) === contato.telefoneE164);
const marcadas = entidades.filter(row => {
  const value = row['Não gerar lead'] ?? row['c-H-mEhOwZkj'] ?? row.values?.['c-H-mEhOwZkj'];
  return value === true || texto(value).toLowerCase() === 'true';
});
return [{ json: { ...contato, naoGerarLead: marcadas.length > 0,
