const contato = $('Code in JavaScript').first().json;
const linhas = $input.all().map(item => item.json)
  .filter(row => typeof row.id === 'string' && /^i-[A-Za-z0-9_-]{1,100}$/.test(row.id));
const normalize = value => String(value ?? '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .trim().toLowerCase();
const statusName = value => {
  if (Array.isArray(value)) return value.map(statusName).join(', ');
  if (value && typeof value === 'object')
    return value.name ?? value.display ?? value.value ?? value.text ?? value.label ?? '';
  return String(value ?? '');
};
const channelId = value =>
  typeof value === 'object' && value !== null ? value.rowId ?? '' : String(value ?? '');
const isWhatsApp = row =>
  /^evo:funix_comercial:[A-Za-z0-9:_-]{1,128}$/.test(String(row.fx_UUID ?? '').trim()) &&
  String(row['api_ID Omnichanel'] ?? '') === contato.whatsappJid &&
  channelId(row.funil_Canal) === 'i-O01Tgl0bN2';
const atendimentos = linhas.filter(isWhatsApp);
const closed = new Set(['orcamento rejeitados','fim negativo','fim positivo']);
const knownOpen = new Set([
  'novo lead (30min)','aguardando dados (24h)','em negociacao (48h)',
  'morno (3 dias)','frio (5 dias)','agendado','entrou',
]);
const unknownStatus = atendimentos.some(r => {
  const st = normalize(statusName(r.at_StatusComercial));
  return !closed.has(st) && !knownOpen.has(st);
});
// Only records referring to THIS JID or THIS exact message can block.
// Other clients' WhatsApp rows must not become a global exception.
const unknownOrigin = linhas.some(r => {
  const marker=String(r.fx_UUID ?? '').trim();
  const sameMessage=marker===contato.fx_UUID;
  const sameConversation=String(r['api_ID Omnichanel'] ?? '')===contato.whatsappJid;
  return (sameMessage || sameConversation) &&
    /^evo:funix_comercial:[A-Za-z0-9:_-]{1,128}$/.test(marker) &&
    !isWhatsApp(r);
});
const eventoJaGravado = atendimentos.some(r => String(r.fx_UUID ?? '').trim() === contato.fx_UUID);
const anteriorEncerrado = atendimentos.find(r => closed.has(normalize(statusName(r.at_StatusComercial))));
const abertos = atendimentos.filter(r => knownOpen.has(normalize(statusName(r.at_StatusComercial))));
const ambiguidade = abertos.length > 1;
const bloquear = unknownStatus || unknownOrigin || ambiguidade;
const criarCard = !bloquear && !eventoJaGravado && abertos.length === 0;
return [{json:{
  ...contato, atendimentosEncontrados: atendimentos.length, atendimentosAbertos: abertos.length,
  criarCard, motivo: unknownOrigin ? 'Origem WhatsApp inconsistente'
    : unknownStatus ? 'Status comercial desconhecido'
    : ambiguidade ? 'Múltiplos Atendimentos comerciais elegíveis'
    : eventoJaGravado ? 'Evento já registrado'
    : abertos.length ? 'Atendimento em aberto'
    : atendimentos.length ? 'Retorno após atendimento encerrado' : 'Contato novo',
  idsAbertos: abertos.map(r=>r.id),
  atendimentoAnteriorId: anteriorEncerrado?.id ?? ''
}}];

