// PREPARAÇÃO SOMENTE. Não assina, não envia nem grava em outbox.
// Executa APÓS nova consulta Coda, para "criado" ou "existente".
const source = $('Code in JavaScript').first().json;
const decision = $('Code in JavaScript1').first().json;
// Motivos de exceção nunca entram no envio, mesmo havendo uma ficha aberta.
if (!['Atendimento em aberto','Evento já registrado','Retorno após atendimento encerrado','Contato novo'].includes(String(decision.motivo ?? ''))) return [];
const policy = $('Verificar opção Não gerar lead').first().json;
if (policy.naoGerarLead !== false) return [];
if (source.instancia !== 'funix_comercial') return [];
if (!/^[0-9]{8,15}@s\.whatsapp\.net$/.test(String(source.whatsappJid ?? ''))) return [];
const pn = source.whatsappJid.split('@')[0];
// Número normalizado pelo CRM pode divergir do PN real; nunca forçar igualdade.
const phoneVerified = source.telefoneE164 === '+' + pn ? source.telefoneE164 : null;
if (!Number.isSafeInteger(source.occurredAt) || source.occurredAt < 0 || source.occurredAt > 2147483647) return [];
if (!/^[A-Za-z0-9:_-]{1,160}$/.test(String(source.fx_UUID ?? ''))) return [];
const name = source.nome || '';
if (typeof name !== 'string' || name.length > 250 || /[\u0000-\u001f\u007f]/.test(name)) return [];
const rows = $input.all().map(item => item.json)
  .filter(r => r && typeof r.id === 'string' && /^i-[A-Za-z0-9_-]{1,100}$/.test(r.id));
const matchingEvent = rows.filter(r => String(r.fx_UUID ?? '').trim() === source.fx_UUID);
let canonical = [];
if (decision.criarCard === true || decision.motivo === 'Evento já registrado') {
  canonical = matchingEvent;
} else if (Array.isArray(decision.idsAbertos) && decision.idsAbertos.length === 1) {
  canonical = rows.filter(r => r.id === decision.idsAbertos[0]);
}
if (canonical.length !== 1) return []; // falha fechada: 0 ou múltiplos
const row = canonical[0];
// Proteção do MVP: telefone coincidente não autoriza replicar cadastro ERP manual.
if (!/^evo:funix_comercial:[A-Za-z0-9:_-]{1,128}$/.test(String(row.fx_UUID ?? '').trim())) return [];
// A linha confirmada deve pertencer ao mesmo JID e canal comercial.
const idOmni = String(row['api_ID Omnichanel'] ?? '');
const canal = row.funil_Canal && typeof row.funil_Canal === 'object'
  ? String(row.funil_Canal.rowId ?? '') : String(row.funil_Canal ?? '');
if (idOmni !== source.whatsappJid || canal !== 'i-O01Tgl0bN2') return [];
const returnedPhone = row.funil_contatoE164;
if (returnedPhone != null && returnedPhone !== '' && String(returnedPhone) !== source.telefoneE164) return [];
const payload = {
  version: 1,
  source: 'coda',
  eventId: source.fx_UUID,
  codaRowId: row.id,
  instance: 'funix_comercial',
  remoteJid: source.whatsappJid,
  phoneE164: phoneVerified,
  displayName: name,
  occurredAt: source.occurredAt
};
return [{json:{status:'READY_FOR_OUTBOX_NOT_SENT', eventId:payload.eventId, codaRowId:payload.codaRowId, bodyJson:JSON.stringify(payload)}}];

